package org.securemail.identity;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Real SQL/signature checks with explicit trusted ACL fixture; no claim of a deployed role bridge. */
class CriticalApprovalTest {
    @TempDir Path home;IdentityStore store;IdentityStoreTest.MutableClock clock;KeyPair service;byte[] audit;Person owner,second;Set<String> delegated=new HashSet<>();
    record Person(KeyPair root,KeyPair device,KeyPair recovery,KeyPair app,String account,String deviceId,long generation) { }
    static KeyPair pair()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
    static byte[] key(KeyPair k){return k.getPublic().getEncoded();}
    @BeforeEach void setup()throws Exception {service=pair();clock=new IdentityStoreTest.MutableClock();audit=new byte[32];new SecureRandom().nextBytes(audit);store=new IdentityStore(home.resolve("identity.db"),service,audit,clock,delegated::contains);owner=register();second=register();IdentityStore.OwnerChallenge c=store.ownerChallenge(owner.account);store.bootstrapOwner(owner.account,c.challenge(),IdentityProtocol.sign(owner.root.getPrivate(),IdentityProtocol.ownerBootstrap(store.audience(),owner.account,c.challenge(),c.expiresAt())));delegated.add(second.account);}
    @AfterEach void close()throws Exception{store.close();}
    Person register()throws Exception {KeyPair root=pair(),device=pair(),recovery=pair(),app=pair();String n=IdentityProtocol.nonce();byte[] p=IdentityProtocol.registration(store.audience(),key(root),key(device),key(recovery),"Пользователь",clock.millis(),n);IdentityStore.Session s=store.register(key(root),key(device),key(recovery),"Пользователь",clock.millis(),n,IdentityProtocol.sign(root.getPrivate(),p),IdentityProtocol.sign(device.getPrivate(),p));return new Person(root,device,recovery,app,s.accountId(),s.deviceId(),s.generation());}
    Capability admin(Person p){IdentityStore.Challenge c=store.stepUpChallenge(p.account,p.deviceId,p.generation);byte[] step=IdentityProtocol.stepUp(store.audience(),p.account,p.deviceId,c.challenge(),c.expiresAt());store.stepUp(p.account,p.deviceId,p.generation,c.challenge(),IdentityProtocol.sign(p.root.getPrivate(),step),IdentityProtocol.sign(p.device.getPrivate(),step));String n=IdentityProtocol.nonce();byte[] body=IdentityProtocol.capabilityRequest(store.audience(),p.account,p.deviceId,p.generation,App.AEGIS,key(p.app),EnumSet.of(Scope.ADMIN),600000,clock.millis(),n);return store.issueCapability(p.account,p.deviceId,p.generation,App.AEGIS,key(p.app),EnumSet.of(Scope.ADMIN),600000,clock.millis(),n,IdentityProtocol.sign(p.device.getPrivate(),body),IdentityProtocol.sign(p.app.getPrivate(),body));}
    Map<String,Object> request(Person p,Capability c,String operation,byte[] body){String nonce=IdentityProtocol.nonce();byte[] canonical=IdentityProtocol.criticalApproval(store.audience(),p.account,operation,nonce,body,clock.millis()+300000);return store.requestCritical(c,operation,body,clock.millis(),nonce,IdentityProtocol.sign(p.app.getPrivate(),IdentityProtocol.requestDigest(c,"admin.execute",IdentityProtocol.digest(canonical),clock.millis(),nonce)));}
    void approve(Person p,Capability c,Map<String,Object> request,byte[] body){String nonce=IdentityProtocol.nonce();byte[] canonical=IdentityProtocol.criticalApproval(store.audience(),p.account,(String)request.get("operation"),(String)request.get("requestId"),body,(Long)request.get("expiresAt"));store.approveCritical(c,(String)request.get("requestId"),clock.millis(),nonce,IdentityProtocol.sign(p.app.getPrivate(),IdentityProtocol.requestDigest(c,"admin.execute",IdentityProtocol.digest(canonical),clock.millis(),nonce)));}
    void consume(Person p,Capability c,Map<String,Object> request,byte[] body){String nonce=IdentityProtocol.nonce();byte[] canonical=IdentityProtocol.criticalApproval(store.audience(),p.account,(String)request.get("operation"),(String)request.get("requestId"),body,(Long)request.get("expiresAt"));store.consumeCritical(c,(String)request.get("requestId"),(String)request.get("operation"),body,clock.millis(),nonce,IdentityProtocol.sign(p.app.getPrivate(),IdentityProtocol.requestDigest(c,"admin.execute",IdentityProtocol.digest(canonical),clock.millis(),nonce)));}
    @Test void twoIndependentCurrentAdministratorsExactPayloadOneUse(){Capability first=admin(owner),other=admin(second);byte[] body={1,2,3};Map<String,Object> r=request(owner,first,"configuration.replace",body);assertThrows(IdentityException.class,()->approve(owner,first,r,body));assertThrows(IdentityException.class,()->consume(owner,first,r,body));approve(second,other,r,body);assertThrows(IdentityException.class,()->consume(owner,first,r,new byte[]{9}));consume(owner,first,r,body);assertThrows(IdentityException.class,()->consume(owner,first,r,body));assertTrue(store.verifyAudit());}
    @Test void revokedSecondAdministratorCannotConfirmOrCompleteExistingPermit(){Capability first=admin(owner),other=admin(second);byte[] body={4};Map<String,Object> r=request(owner,first,"backup.restore",body);approve(second,other,r,body);delegated.remove(second.account);assertFalse(store.isActive(other));assertThrows(IdentityException.class,()->consume(owner,first,r,body));assertThrows(IdentityException.class,()->admin(second));}
    @Test void expiredStepUpAndNewSessionOfApproverInvalidatePermit(){Capability first=admin(owner),other=admin(second);byte[] body={5};Map<String,Object> r=request(owner,first,"backup.restore",body);approve(second,other,r,body);String n=IdentityProtocol.nonce();store.login(second.account,second.deviceId,clock.millis(),n,IdentityProtocol.sign(second.device.getPrivate(),IdentityProtocol.login(store.audience(),second.account,second.deviceId,clock.millis(),n)));assertThrows(IdentityException.class,()->consume(owner,first,r,body));}
    @Test void administrativeFreshCheckExpiresWithStepUpRatherThanLongerTokenLease(){Capability cap=admin(owner);assertTrue(store.isActive(cap));clock.value+=120000;assertFalse(store.isActive(cap));}
    @Test void releasesRemainOwnerOnlyWithoutSecondApproval(){Capability first=admin(owner),other=admin(second);byte[] digest=IdentityProtocol.digest(new byte[]{8});String n=IdentityProtocol.nonce();assertTrue(store.ownerReleaseApproval(first,digest,clock.millis(),n,IdentityProtocol.sign(owner.app.getPrivate(),IdentityProtocol.request(first,"admin.execute",digest,clock.millis(),n))));String n2=IdentityProtocol.nonce();assertThrows(IdentityException.class,()->store.ownerReleaseApproval(other,digest,clock.millis(),n2,IdentityProtocol.sign(second.app.getPrivate(),IdentityProtocol.request(other,"admin.execute",digest,clock.millis(),n2))));assertThrows(IdentityException.class,()->request(owner,first,"release.publish",digest));}
}
